from fractions import Fraction
def solve(label, in_a, in_b):
    b = 0
    ab = 0
    a = 0
    for x in range(1, 7):
        for y in range(1, 7):
            if in_b(x, y):
                b = b + 1
                if in_a(x, y):
                    ab = ab + 1
            if in_a(x, y):
                a = a + 1
    print(label)
    print(f"  |B| = {b}, |A and B| = {ab}")
    print(f"  P(A | B) = {ab}/{b} = {Fraction(ab, b)}, while P(A) = {Fraction(a, 36)}")
solve("Case 1 · given one die: sum 8 given first die 3", lambda x, y: x + y == 8, lambda x, y: x == 3)
solve("Case 2 · given the sum: first die 3 given sum 8", lambda x, y: x == 3, lambda x, y: x + y == 8)
solve("Case 3 · given at least one: both 6 given a 6", lambda x, y: x == 6 and y == 6, lambda x, y: x == 6 or y == 6)
solve("Case 4 · independent: first even given sum 7", lambda x, y: x % 2 == 0, lambda x, y: x + y == 7)

