from fractions import Fraction
def solve(t):
    b = 0
    both = 0
    for x in range(1, 7):
        for y in range(1, 7):
            if x + y >= t:
                b = b + 1
                if x == y:
                    both = both + 1
    print(f"sum at least {t}")
    print(f"  |B| = {b}, doubles in B: {both}")
    print(f"  P(doubles | sum at least {t}) = {both}/{b} = {Fraction(both, b)}")
    print(f"  P(sum at least {t} | doubles) = {both}/6 = {Fraction(both, 6)}")
k = int(input())
for i in range(k):
    solve(int(input()))
